CREATE OR REPLACE FUNCTION public.pos_get_cash_station_state(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_actor_key text;
  v_role text;
  v_station public.pos_cash_stations;
  v_own_session public.pos_cash_sessions;
  v_station_open public.pos_cash_sessions;
  v_other_station_session public.pos_cash_sessions;
  v_status text;
  v_code text;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  perform private.assert_cloud_cash_sync_enabled(v_context);
  perform private.assert_cash_permission(v_context);

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_role := coalesce(v_context->>'device_role', 'staff');
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_station := private.resolve_cash_station_for_device(v_license_id, v_device_id, true);

  select * into v_own_session
    from public.pos_cash_sessions s
   where s.license_id = v_license_id
     and s.cash_station_id = v_station.id
     and s.actor_key = v_actor_key
     and s.status = 'open'
     and s.deleted_at is null
   order by s.opened_at desc
   limit 1;

  select * into v_station_open
    from public.pos_cash_sessions s
   where s.license_id = v_license_id
     and s.cash_station_id = v_station.id
     and s.status = 'open'
     and s.deleted_at is null
   order by s.opened_at desc
   limit 1;

  select * into v_other_station_session
    from public.pos_cash_sessions s
   where s.license_id = v_license_id
     and s.actor_key = v_actor_key
     and s.status = 'open'
     and s.deleted_at is null
     and s.cash_station_id is distinct from v_station.id
   order by s.opened_at desc
   limit 1;

  if v_station_open.id is not null and v_station_open.actor_key <> v_actor_key then
    v_status := 'HANDOFF_REQUIRED';
    v_code := 'CASH_HANDOFF_REQUIRED';
  elsif v_own_session.id is not null then
    v_status := 'OWN_SESSION_OPEN';
    v_code := null;
  elsif v_role = 'staff' and v_other_station_session.id is not null then
    v_status := 'BLOCKED';
    v_code := 'CASH_SESSION_ALREADY_OPEN';
  else
    v_status := 'NO_SESSION';
    v_code := null;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'success', true,
    'financial_status', v_status,
    'financial_code', v_code,
    'cash_station', to_jsonb(v_station),
    'cash_session', case when v_own_session.id is null then null else private.pos_cash_session_to_jsonb(v_own_session) end,
    'station_open_cash_session', case when v_station_open.id is null then null else private.pos_cash_session_to_jsonb(v_station_open) end,
    'actor_key', v_actor_key,
    'cash_station_id', v_station.id,
    'sync_context', jsonb_strip_nulls(jsonb_build_object(
      'device_role', v_context->>'device_role',
      'staff_user_id', v_context->>'staff_user_id',
      'admin_user_id', v_context->>'admin_user_id',
      'cash_station_id', v_station.id
    ))
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_admin_adopt_legacy_cash_session(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rate_limit jsonb;
begin
  v_rate_limit := public.enforce_pos_rpc_rate_limit_v2(
    p_license_key := p_license_key, p_device_fingerprint := p_device_fingerprint,
    p_staff_session_token := p_staff_session_token, p_rpc_name := 'pos_admin_adopt_legacy_cash_session',
    p_scope := 'POS_WRITE', p_max_attempts := 20, p_window_seconds := 600, p_block_seconds := 300,
    p_code := 'RPC_RATE_LIMITED', p_metadata := '{}'::jsonb
  );
  if coalesce((v_rate_limit->>'allowed')::boolean, false) is false then
    return public.build_pos_rpc_rate_limited_response(v_rate_limit);
  end if;
  return public.pos_admin_adopt_legacy_cash_session_unlimited(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
    p_cash_session_id, p_expected_version, p_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_staff_users(p_license_key text, p_admin_device_fingerprint text, p_admin_security_token text, p_admin_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth jsonb;
begin
  v_auth := private.require_active_admin_session(
    p_license_key,
    p_admin_device_fingerprint,
    p_admin_security_token,
    p_admin_session_token
  );
  if coalesce((v_auth->>'success')::boolean, false) is false then
    return v_auth;
  end if;

  return private.admin_list_staff_users_impl((v_auth->>'license_id')::uuid);
end;
$function$

